import type { PostBlock } from '../data/posts';
import { useLang } from '../i18n/useLang';
import { COPY } from '../locales/copy';

interface Props {
  blocks: PostBlock[];
  /** Language of the post's headings when it differs from the page (postTextLang). */
  textLang?: string;
}

/**
 * TableOfContents — extracts H2 headings from post blocks and renders a
 * sticky sidebar. Headings link to anchor ids generated by the Post page.
 * Hidden on small screens — reading long-form on mobile shouldn't fight a
 * sidebar for space.
 */
export default function TableOfContents({ blocks, textLang }: Props) {
  const c = COPY[useLang()].chrome;
  const headings = blocks
    .map((b, i) => ({ block: b, index: i }))
    .filter(
      (x): x is { block: Extract<PostBlock, { type: 'heading' }>; index: number } =>
        x.block.type === 'heading' && x.block.level === 2
    );

  if (headings.length < 2) return null;

  return (
    <nav aria-label={c.inThisStory}>
      <p className="text-base font-bold text-[var(--color-ink)] mb-3" style={{ fontFamily: "var(--font-editorial)" }}>
        {c.inThisStory}
      </p>
      <ul lang={textLang} className="space-y-2.5 border-l border-[var(--color-paper-border)]">
        {headings.map(({ block, index }) => {
          const id = `h-${index}`;
          return (
            <li key={id}>
              <a
                href={`#${id}`}
                className="block pl-4 -ml-px border-l-2 border-transparent text-[15px] text-[var(--color-ink-soft)] hover:text-[var(--color-accent)] hover:border-[var(--color-accent)] transition-colors leading-snug"
              >
                {block.text}
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
